package org.michimusic.mobile.ui.screens

import android.util.Base64

/** Shared fixture: a real 64x32 RGB PNG, independent of the production encoder. */
internal object PlaylistTestImages {
    private const val PNG_64X32_BASE64 =
        ""

    val png64x32: ByteArray by lazy { Base64.decode(PNG_64X32_BASE64, Base64.DEFAULT) }
}
